mn.addEventListener("change",e=>{if(cur!=="sj"||!sjf)return;const t=e.target,k=t.dataset.sf;if(!k)return;
if(k==="tgl"&&!sjei){const n=document.getElementById("sjno");if(n)n.textContent=sjNo(t.value)}
if(k==="nama"){const i=+t.dataset.i,m=S.material.find(x=>x.nama===t.value),it=sjf.items[i];if(m&&!it.satuan){it.satuan=m.satuan;const q=mn.querySelector('input[data-sf="satuan"][data-i="'+i+'"]');if(q)q.value=m.satuan}}});
mn.addEventListener("click",e=>{if(cur!=="sj")return;const b=e.target.closest("[data-sj]");if(!b)return;const a=b.dataset.sj,id=b.dataset.id,r=S.sj.find(x=>x.id===id);
if(a==="add")sjf.items.push({});
else if(a==="ei"){const q=mn.querySelector('input[data-sf="nama"][data-i="'+b.dataset.i+'"]');if(q){q.focus();q.select()}return}
else if(a==="x"){sjf.items.splice(+b.dataset.i,1);if(!sjf.items.length)sjf.items.push({})}
else if(a==="save"){if(!(sjf.proyek||"").trim()){alert("Isi proyek / customer dulu");return}const its=sjf.items.filter(x=>(x.nama||"").trim());if(!its.length||its.some(x=>!(+x.qty>0))){alert("Isi minimal 1 barang beserta Qty-nya");return}
const x=JSON.parse(JSON.stringify(sjf));x.items=its;if(sjei){const i=S.sj.findIndex(y=>y.id===sjei);x.id=sjei;x.no=S.sj[i].no;S.sj[i]=x}else{x.id=uid();x.no=sjNo(x.tgl);S.sj.push(x)}sjf=newSJ();sjei=null}
else if(a==="cancel"){sjf=newSJ();sjei=null}
else if(a==="p"&&r){printSJ(r);return}
else if(a==="e"&&r){sjf=JSON.parse(JSON.stringify(r));while(sjf.items.length<3)sjf.items.push({});sjei=r.id;scrollTo(0,0)}
else if(a==="d"&&r){if(!confirm("Hapus surat jalan ini?"))return;S.sj=S.sj.filter(x=>x!==r);if(sjei===id){sjf=newSJ();sjei=null}}
else return;
save();render()});

