mn.addEventListener("input",e=>{const k=e.target.dataset.fe;if(!k||!fre)return;fre.f[k]=e.target.value;const j=document.getElementById("fejml");if(j)j.textContent=fmt((+fre.f.qty||0)*(+fre.f.harga||0))});
go("dashboard");
